POSTS=[]; COMMENTS={}; CHATS={}; MESSAGES={}; INTERACTIONS={}; FRIENDS=set(); SETTINGS={"demo":{"two_factor":False,"active_status":True,"app_lock":0,"default_audience":"PUBLIC"}}
# === الخوارزميات الحقيقية - بتشتغل ===
def feed_algo(posts, user_id="demo"):
    # كل تفاعل بيزود النقاط - و كل ما تتفاعل مع صاحبك - بيطلع فوق
    out=[]
    for p in posts:
        likes=p.get("likes_count",0); comments=p.get("comments_count",0); shares=p.get("shares_count",0)
        # نقاط التفاعل مع المؤلف - لو اتفاعلت معاه قبل كده - بياخد +50
        affinity = INTERACTIONS.get(p.get("author_id"),0)*10
        # حداثة - الجديد بياخد نقاط اكتر
        recency = 10
        score = likes*2 + comments*3 + shares*4 + affinity + recency
        pp=dict(p); pp["algo_score"]=score; pp["algo_reason"]=f"لايك {likes}×2 + تعليق {comments}×3 + تفاعلك معاه {affinity} = {score}"
        out.append(pp)
    return sorted(out, key=lambda x: x["algo_score"], reverse=True)
def suggest_algo():
    # اصدقاء مشتركين حقيقي - لو ضفت واحد - بيختفي و بيجي غيره
    all_people=[("أحمد علي","عطبرة",5),("سارة محمد","الخرطوم",12),("يوسف إبراهيم","عطبرة",8),("خديجة حسن","مدني",3)]
    res=[]
    for n,c,m in all_people:
        if n not in FRIENDS:
            res.append({"id":str(uuid.uuid4()),"name":n,"city":c,"mutual":m,"algo_reason":f"{m} أصدقاء مشتركين - عشان كده اقترحناه"})
    return res
def privacy_algo(s):
    score=100; recs=[]
    if not s.get("two_factor"): score-=30; recs.append("فعّل المصادقة الثنائية +30%")
    if s.get("default_audience")=="PUBLIC": score-=15; recs.append("خلي منشوراتك للأصدقاء +15%")
    if not s.get("app_lock"): score-=10; recs.append("فعّل قفل الشات +10%")
    if s.get("active_status"): score-=5; recs.append("اخفي حالة النشاط +5%")
    return {"score":max(0,score),"status":"ممتاز 🟢" if score>=85 else "جيد 🟡" if score>=70 else "خطر 🔴","fixes":recs,"reason":f"نقاطك {score} - لأنك {len(recs)} حاجات ما عملتها"}
def ato_algo(ip_country,last_country,hours,is_new,failed):
    # لو دولة مختلفة + جهاز جديد + وقت قصير = خطر عالي
    travel=1 if ip_country!=last_country and hours<2 else 0
    z= (travel*1.2 + (1 if is_new else 0)*0.8 + failed*0.3) - 1.0
    risk=round(1/(1+math.exp(-z)),2)
    return {"risk":risk,"action":"BIOMETRIC - اطلب بصمة" if risk>=0.6 else "ALLOW - دخول عادي","reason":f"دولة {ip_country} vs {last_country} - جهاز جديد {is_new} - محاولات فاشلة {failed}"}

